// Emits one item per configured asset. Adding an asset = ONE array entry
// here; node count and wiring never change (that is the point of this shape).
//
// ASSET_ALLOWLIST and isAllowedAsset no longer exist in src/market/assets.ts
// (removed by the dynamic-asset-count change). /api/cycle now validates each
// symbol by format only (isWellFormedAsset, pattern ^[A-Z0-9]{2,20}USDT$),
// independent of any list, plus a standalone MAX_ASSETS=25 cap. Adding or
// removing a symbol here needs no app-side change beyond staying within
// that cap (openspec/changes/dynamic-asset-count/proposal.md).
const SYMBOLS = [
  'BTCUSDT', 
  'ETHUSDT', 
  'SOLUSDT',
  'DOTUSDT'
];

// pairedItem is stated explicitly: every symbol item derives from the single
// Schedule Trigger item. This keeps n8n's item-linking chain complete for the
// downstream $('Symbols').item back-reference in 'Set Symbol'.
return SYMBOLS.map((symbol) => ({ json: { symbol }, pairedItem: { item: 0 } }));

// Each incoming item carries one asset's symbol + raw Binance klines
// response (array of [openTime, open, high, low, close, volume, closeTime, ...]),
// both attached explicitly by the per-branch 'Set Symbol - {SYMBOL}' node
// upstream. No positional (item-order) inference is used here.

function toCandle(row) {
  return {
    openTime: Number(row[0]),
    open: Number(row[1]),
    high: Number(row[2]),
    low: Number(row[3]),
    close: Number(row[4]),
    volume: Number(row[5]),
  };
}

const assets = items.map((item) => ({
  symbol: item.json.symbol,
  klines: item.json.klines.map(toCandle),
}));

return [{ json: { assets } }];
